import{_ as t,o as a,c as r,al as i}from"./chunks/framework.7vp1BMOE.js";const f=JSON.parse('{"title":"Arm, Disarm, Prearm Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"en/advanced_config/prearm_arm_disarm.md","filePath":"en/advanced_config/prearm_arm_disarm.md"}'),o={name:"en/advanced_config/prearm_arm_disarm.md"};function s(n,e,l,m,d,c){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="arm-disarm-prearm-configuration" tabindex="-1">Arm, Disarm, Prearm Configuration <a class="header-anchor" href="#arm-disarm-prearm-configuration" aria-label="Permalink to &quot;Arm, Disarm, Prearm Configuration&quot;">​</a></h1><p>Vehicles may have moving parts, some of which are potentially dangerous when powered (in particular motors and propellers)!</p><p>To reduce the chance of accidents, PX4 has explicit state(s) for powering the vehicle components:</p><ul><li><strong>Disarmed:</strong> There is no power to motors or actuators.</li><li><strong>Pre-armed:</strong> Motors/propellers are locked but actuators for non-dangerous electronics are powered (e.g. ailerons, flaps etc.).</li><li><strong>Armed:</strong> Vehicle is fully powered. Motors/propellers may be turning (dangerous!)</li></ul><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Ground stations may display <em>disarmed</em> for pre-armed vehicles. While not technically correct for pre-armed vehicles, it is &quot;safe&quot;.</p></div><p>Users can control progression though these states using a <a href="./../getting_started/px4_basic_concepts#safety-switch">safety switch</a> on the vehicle (optional) <em>and</em> an <a href="#arm_disarm_switch">arming switch/button</a>, <a href="#arm_disarm_gestures">arming gesture</a>, or <em>MAVLink command</em> on the ground controller:</p><ul><li><p>A <em>safety switch</em> is a control <em>on the vehicle</em> that must be engaged before the vehicle can be armed, and which may also prevent pre-arming (depending on the configuration). Commonly the safety switch is integrated into a GPS unit, but it may also be a separate physical component.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>A vehicle that is armed is potentially dangerous. The safety switch is an additional mechanism that prevents arming from happening by accident.</p></div></li><li><p>An <em>arming switch</em> is a switch or button <em>on an RC controller</em> that can be used to arm the vehicle and start motors (provided arming is not prevented by a safety switch).</p></li><li><p>An <em>arming gesture</em> is a stick movement <em>on an RC controller</em> that can be used as an alternative to an arming switch.</p></li><li><p>MAVLink commands can also be sent by a ground control station to pre-arm, arm, or disarm a vehicle.</p></li></ul><p>PX4 will also automatically disarm the vehicle if it does not takeoff within a certain amount of time after arming, and if it is not manually disarmed after landing. This reduces the amount of time where an armed (and therefore dangerous) vehicle is on the ground.</p><p>PX4 allows you to configure how pre-arming, arming and disarming work using parameters (which can be edited in <em>QGroundControl</em> via the <a href="./../advanced_config/parameters">parameter editor</a>), as described in the following sections.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Arming/disarming parameters can be found in <a href="./../advanced_config/parameter_reference#commander">Parameter Reference &gt; Commander</a> (search for <code>COM_ARM_*</code> and <code>COM_DISARM_*</code>).</p></div><h2 id="arm_disarm_gestures" tabindex="-1">Arming/Disarming Gestures <a class="header-anchor" href="#arm_disarm_gestures" aria-label="Permalink to &quot;Arming/Disarming Gestures {#arm_disarm_gestures}&quot;">​</a></h2><p>By default, the vehicle is armed and disarmed by moving RC throttle/yaw sticks to particular extremes and holding them for 1 second.</p><ul><li><strong>Arming:</strong> Throttle minimum, yaw maximum</li><li><strong>Disarming:</strong> Throttle minimum, yaw minimum</li></ul><p>RC controllers will use different sticks for throttle and yaw <a href="./../getting_started/rc_transmitter_receiver#types-of-remote-controllers">based on their mode</a>, and hence different gestures:</p><ul><li><strong>Mode 2</strong>: <ul><li><em>Arm:</em> Left stick to bottom right.</li><li><em>Disarm:</em> Left stick to the bottom left.</li></ul></li><li><strong>Mode 1</strong>: <ul><li><em>Arm:</em> Left-stick to right, right-stick to bottom.</li><li><em>Disarm:</em> Left-stick to left, right-stick to the bottom.</li></ul></li></ul><p>Note that disarming in any altitude controlled mode is only possible after landing was detected. In manually piloted modes without altitude control, such as Stabilized, Acro, and Manual, it&#39;s always possible to disarm using gestures or buttons — even in flight.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><a id="MAN_ARM_GESTURE"></a><a href="./../advanced_config/parameter_reference#MAN_ARM_GESTURE">MAN_ARM_GESTURE</a></td><td>Enable arm/disarm stick guesture. <code>0</code>: Disabled, <code>1</code>: Enabled (default).</td></tr></tbody></table><h2 id="arm_disarm_switch" tabindex="-1">Arming Button/Switch <a class="header-anchor" href="#arm_disarm_switch" aria-label="Permalink to &quot;Arming Button/Switch {#arm_disarm_switch}&quot;">​</a></h2><p>An <em>arming button</em> or &quot;momentary switch&quot; can be configured to trigger arm/disarm <em>instead</em> of <a href="#arm_disarm_gestures">gesture-based arming</a> (setting an arming switch disables arming gestures). The button should be held down for one second to arm (when disarmed) or disarm (when armed).</p><p>A two-position switch can also be used for arming/disarming, where the respective arm/disarm commands are sent on switch <em>transitions</em>.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Two-position arming switches are primarily used in/recommended for racing drones.</p></div><p>The switch or button is assigned (and enabled) using <a href="#RC_MAP_ARM_SW">RC_MAP_ARM_SW</a>, and the switch &quot;type&quot; is configured using <a href="#COM_ARM_SWISBTN">COM_ARM_SWISBTN</a>.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><a id="RC_MAP_ARM_SW"></a><a href="./../advanced_config/parameter_reference#RC_MAP_ARM_SW">RC_MAP_ARM_SW</a></td><td>RC arm switch channel (default: 0 - unassigned). If defined, the specified RC channel (button/switch) is used for arming instead of a stick gesture. <br><strong>Note:</strong><br>- This setting <em>disables the stick gesture</em>!<br>- This setting applies to RC controllers. It does not apply to Joystick controllers that are connected via <em>QGroundControl</em>.</td></tr><tr><td><a id="COM_ARM_SWISBTN"></a><a href="./../advanced_config/parameter_reference#COM_ARM_SWISBTN">COM_ARM_SWISBTN</a></td><td>Arm switch is a momentary button. <br>- <code>0</code>: Arm switch is a 2-position switch where arm/disarm commands are sent on switch transitions.<br>-<code>1</code>: Arm switch is a momentary button where the arm/disarm command is sent after holding down the button for one second.</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The switch can also be set as part of <em>QGroundControl</em> <a href="./../config/flight_mode">Flight Mode</a> configuration.</p></div><h2 id="auto-disarming" tabindex="-1">Auto-Disarming <a class="header-anchor" href="#auto-disarming" aria-label="Permalink to &quot;Auto-Disarming&quot;">​</a></h2><p>By default vehicles will automatically disarm on landing, or if you take too long to take off after arming. The feature is configured using the following timeouts.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><a id="COM_DISARM_LAND"></a><a href="./../advanced_config/parameter_reference#COM_DISARM_LAND">COM_DISARM_LAND</a></td><td>Time-out for auto disarm after landing. Default: 2s (-1 to disable).</td></tr><tr><td><a id="COM_DISARM_PRFLT"></a><a href="./../advanced_config/parameter_reference#COM_DISARM_PRFLT">COM_DISARM_PRFLT</a></td><td>Time-out for auto disarm if too slow to takeoff. Default: 10s (-1 to disable).</td></tr></tbody></table><p>By default, the vehicle keeps safety off after disarming. If <a href="#COM_FORCE_SAFETY">COM_FORCE_SAFETY</a> is set to <code>1</code>, safety is re-enabled on disarm, so it must be turned off again (by switch or MAVLink command, depending on <a href="#COM_SAFETY_MODE">COM_SAFETY_MODE</a>) before the next arming. In modes that pre-arm when safety is turned off, this also exits the pre-armed state. This parameter has no effect when <code>COM_SAFETY_MODE</code> is set to <code>0</code>.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><a id="COM_FORCE_SAFETY"></a><a href="./../advanced_config/parameter_reference#COM_FORCE_SAFETY">COM_FORCE_SAFETY</a></td><td>Re-enable safety when the vehicle disarms. Default: <code>0</code> (Disabled).</td></tr></tbody></table><h2 id="auto-arming-on-boot" tabindex="-1">Auto-Arming on Boot <a class="header-anchor" href="#auto-arming-on-boot" aria-label="Permalink to &quot;Auto-Arming on Boot&quot;">​</a></h2><p>The vehicle can be configured to arm automatically on boot once all preflight checks pass, using the <code>COM_ARM_ON_BOOT</code> parameter. For safety, PX4 enforces a minimum 5-second delay after boot before attempting to arm.</p><p>Once armed this way, the vehicle will not re-arm automatically after a manual disarm.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The parameter value is read once at boot. Changing it while the system is running has no effect until the next reboot.</p></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Use with caution. A vehicle that arms automatically can spin up motors and actuators without any operator gesture. Ensure the vehicle is in a safe state before powering on.</p></div><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><a id="COM_ARM_ON_BOOT"></a><a href="./../advanced_config/parameter_reference#COM_ARM_ON_BOOT">COM_ARM_ON_BOOT</a></td><td>Arm automatically once preflight checks pass after boot. Default: <code>0</code> (Disabled).</td></tr></tbody></table><h2 id="prearm_checks" tabindex="-1">Pre-Arm Checks <a class="header-anchor" href="#prearm_checks" aria-label="Permalink to &quot;Pre-Arm Checks {#prearm_checks}&quot;">​</a></h2><p>To reduce accidents, vehicles are only allowed to arm certain conditions are met (some of which are configurable). Arming is prevented if:</p><ul><li>The vehicle is not in a &quot;healthy&quot; state. For example it is not calibrated, or is reporting sensor errors.</li><li>The vehicle still has its <a href="#safety_state">safety state</a> set to <em>ON</em>. This could for instance be a <a href="./../getting_started/px4_basic_concepts#safety-switch">safety switch</a> that has not been engaged.</li><li>The vehicle has a <a href="./../peripherals/remote_id">remote ID</a> that is unhealthy or otherwise not ready</li><li>A VTOL vehicle is in fixed-wing mode (<a href="./../advanced_config/parameter_reference#CBRK_VTOLARMING">by default</a>).</li><li>The current mode requires an adequate global position estimate but the vehicle does not have GPS lock.</li><li>Many more (see <a href="./../config/safety#arming-disarming-settings">arming/disarming safety settings</a> for more information).</li></ul><p>The current failed checks can be viewed in QGroundControl (v4.2.0 and later) <a href="./../flying/pre_flight_checks#qgc-arming-check-report">Arming Check Report</a> (see also <a href="https://docs.qgroundcontrol.com/master/en/qgc-user-guide/fly_view/fly_view_toolbar.html#flight-status" target="_blank" rel="noreferrer">Fly View &gt; Toolbar &gt; Flight Status</a>).</p><p>Note that internally PX4 runs arming checks at 10Hz. A list of the failed checks is kept, and if the list changes PX4 emits the current list using the <a href="./../concept/events_interface">Events interface</a>. The list is also sent out when the GCS connects. Effectively the GCS knows the status of pre-arm checks immediately, both when disarmed and armed.</p><details class="details custom-block"><summary>Implementation notes for developers</summary><p>The client implementation is in <a href="https://github.com/mavlink/libevents" target="_blank" rel="noreferrer">libevents</a>:</p><ul><li><a href="https://github.com/mavlink/libevents#event-groups" target="_blank" rel="noreferrer">libevents &gt; Event groups</a></li><li><a href="https://github.com/mavlink/libevents/blob/main/libs/cpp/parse/health_and_arming_checks.h" target="_blank" rel="noreferrer">health_and_arming_checks.h</a></li></ul><p>QGC implementation: <a href="https://github.com/mavlink/qgroundcontrol/blob/master/src/MAVLink/LibEvents/HealthAndArmingCheckReport.cc" target="_blank" rel="noreferrer">HealthAndArmingCheckReport.cc</a>.</p></details><p>PX4 also emits a subset of the arming check information in the <a href="https://mavlink.io/en/messages/common.html#SYS_STATUS" target="_blank" rel="noreferrer">SYS_STATUS</a> message (see <a href="https://mavlink.io/en/messages/common.html#MAV_SYS_STATUS_SENSOR" target="_blank" rel="noreferrer">MAV_SYS_STATUS_SENSOR</a>).</p><h2 id="safety_state" tabindex="-1">Arming Sequence: Safety State <a class="header-anchor" href="#safety_state" aria-label="Permalink to &quot;Arming Sequence: Safety State {#safety_state}&quot;">​</a></h2><p>The arming sequence depends on whether or not there is a <em>safety switch</em>, and is controlled by the parameter <a href="#COM_SAFETY_MODE">COM_SAFETY_MODE</a>. Changes to the parameter only take effect after a reboot.</p><p>When disarmed (or pre-armed), the safety state can either be <em>ON</em> (a.k.a. <em>SAFE</em>), or <em>OFF</em> (a.k.a. <em>DANGEROUS</em>). When it is <em>ON</em>, arming will always be prevented. When it is <em>OFF</em>, the vehicle can be armed for as long as the <a href="#prearm_checks">pre-arm checks</a> have passed.</p><p>Additionally, the <a href="#COM_PREARM_MODE">COM_PREARM_MODE</a> parameter defines when/if pre-arm mode is enabled (&quot;safe&quot;/non-throttling actuators are able to move):</p><ul><li><code>Disabled</code> (Default): Pre-arm mode disabled (there is no stage where only non-throttling actuators are enabled).</li><li><code>When safety off</code>: Pre-arm mode is enabled when safety is turned off.</li><li><code>Always</code>: Pre-arm mode is enabled from power up.</li></ul><p>The sections below detail the startup sequences for the different configurations of <a href="#COM_SAFETY_MODE">COM_SAFETY_MODE</a> and <a href="#COM_PREARM_MODE">COM_PREARM_MODE</a>.</p><h3 id="com-safety-mode-always-off-default-and-com-prearm-mode-disabled-default" tabindex="-1">COM_SAFETY_MODE=Always off (Default) and COM_PREARM_MODE=Disabled (Default) <a class="header-anchor" href="#com-safety-mode-always-off-default-and-com-prearm-mode-disabled-default" aria-label="Permalink to &quot;COM_SAFETY_MODE=Always off (Default) and COM_PREARM_MODE=Disabled (Default)&quot;">​</a></h3><p>The default configuration does not impose any additional safety measures. Arming is possible as soon as the rest of the system is ready.</p><p>The startup sequence is:</p><ol><li>Power-up. <ul><li>All actuators locked into disarmed position</li><li>System safety is off: Arming possible once the other pre-arm checks pass.</li></ul></li><li>Arm command is issued. <ul><li>The system is armed.</li><li>All motors and actuators can move.</li></ul></li></ol><h3 id="com-safety-mode-safety-switch-physical-or-virtual-via-mavlink-and-com-prearm-mode-when-safety-off" tabindex="-1">COM_SAFETY_MODE=Safety switch (physical or virtual via MAVLink) and COM_PREARM_MODE=When safety off <a class="header-anchor" href="#com-safety-mode-safety-switch-physical-or-virtual-via-mavlink-and-com-prearm-mode-when-safety-off" aria-label="Permalink to &quot;COM_SAFETY_MODE=Safety switch (physical or virtual via MAVLink) and COM_PREARM_MODE=When safety off&quot;">​</a></h3><p>This configuration lets you use either the safety switch or a MAVLink command <a href="https://mavlink.io/en/messages/common.html#MAV_CMD_DO_SET_SAFETY_SWITCH_STATE" target="_blank" rel="noreferrer">MAV_CMD_DO_SET_SAFETY_SWITCH_STATE</a> to turn safety off. Note that sending the corresponding MAVLink command with SAFETY<em>SWITCH_STATE_SAFE also lets you turn safety back on, but the physical switch does _not</em> allow to go back to a safe state.</p><p>The startup sequence is:</p><ol><li>Power-up. <ul><li>All actuators locked into disarmed position</li><li>Not possible to arm.</li></ul></li><li>Safety switch is pressed or a MAVLink command is received. <ul><li>System now pre-armed: non-throttling actuators can move (e.g. ailerons).</li><li>System safety is off: Arming possible once the other pre-arm checks pass.</li></ul></li><li>Arm command is issued. <ul><li>The system is armed.</li><li>All motors and actuators can move.</li></ul></li></ol><h3 id="com-safety-mode-physical-safety-switch-only-and-com-prearm-mode-when-safety-off" tabindex="-1">COM_SAFETY_MODE=Physical safety switch only and COM_PREARM_MODE=When safety off <a class="header-anchor" href="#com-safety-mode-physical-safety-switch-only-and-com-prearm-mode-when-safety-off" aria-label="Permalink to &quot;COM_SAFETY_MODE=Physical safety switch only and COM_PREARM_MODE=When safety off&quot;">​</a></h3><p>When safety mode is <code>Physical safety switch only</code>, you must press the safety switch to turn safety off. Note that pressing the safety switch again does <em>not</em> allow to go back to a safe state. The MAVLink command is rejected.</p><p>The startup sequence is:</p><ol><li>Power-up. <ul><li>All actuators locked into disarmed position</li><li>Not possible to arm.</li></ul></li><li>Safety switch is pressed. <ul><li>System now pre-armed: non-throttling actuators can move (e.g. ailerons).</li><li>System safety is off: Arming possible once the other pre-arm checks pass.</li></ul></li><li>Arm command is issued. <ul><li>The system is armed.</li><li>All motors and actuators can move.</li></ul></li></ol><h3 id="com-safety-mode-mavlink-only-and-com-prearm-mode-when-safety-off" tabindex="-1">COM_SAFETY_MODE=MAVLink only and COM_PREARM_MODE=When safety off <a class="header-anchor" href="#com-safety-mode-mavlink-only-and-com-prearm-mode-when-safety-off" aria-label="Permalink to &quot;COM_SAFETY_MODE=MAVLink only and COM_PREARM_MODE=When safety off&quot;">​</a></h3><p>When safety mode is <code>MAVLink only</code>, you must send a MAVLink command <a href="https://mavlink.io/en/messages/common.html#MAV_CMD_DO_SET_SAFETY_SWITCH_STATE" target="_blank" rel="noreferrer">MAV_CMD_DO_SET_SAFETY_SWITCH_STATE</a> to turn safety off. Note that sending the corresponding MAVLink command with SAFETY_SWITCH_STATE_SAFE also lets you turn safety back on. Any physical safety switch is ignored.</p><p>The startup sequence is:</p><ol><li>Power-up. <ul><li>All actuators locked into disarmed position</li><li>Not possible to arm.</li></ul></li><li>A MAVLink command is received. <ul><li>System now pre-armed: non-throttling actuators can move (e.g. ailerons).</li><li>System safety is off: Arming possible once the other pre-arm checks pass.</li></ul></li><li>Arm command is issued. <ul><li>The system is armed.</li><li>All motors and actuators can move.</li></ul></li></ol><h3 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to &quot;Parameters&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><a id="COM_SAFETY_MODE"></a><a href="./../advanced_config/parameter_reference#COM_SAFETY_MODE">COM_SAFETY_MODE</a></td><td>Condition to turn safety off. Vehicle arming is prevented for as long as safety is on.</td></tr><tr><td><a id="COM_PREARM_MODE"></a><a href="./../advanced_config/parameter_reference#COM_PREARM_MODE">COM_PREARM_MODE</a></td><td>Condition to enter the prearmed state.</td></tr></tbody></table>',66)])])}const u=t(o,[["render",s]]);export{f as __pageData,u as default};
